def count_shapes(a, bg):
    cells=[(r,c) for r in range(len(a)) for c in range(len(a[0])) if a[r][c]!=bg]
    seen=set(); cnt=0
    for (r,c) in sorted(cells):
        if (r,c) in seen: continue
        size=1; q=[(r,c)]; seen.add((r,c))
        while q:
            x,y=q.pop(); for dx in (-1,0,1):
                ny=nx=x+dx
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                x2,y2=x+dx,y+dy
                if 0<=x2<len(a) and 0<=y2<len(a[0]) and a[x2][y2]==a[r][c] and (x2,y2) not in seen:
                    seen.add((x2,y2)); size+=1; q.append((x2,y2))
        cnt+=1
    return cnt, max((max(s) for s_ in []) or (len(cells)), key=lambda _: None)
